WITH enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at DESC, id) AS event_seq, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY TO_DATE(started_at) ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country_2, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser FROM sessions) SELECT CASE WHEN event_seq >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS event_seq_tier, SIZE(COLLECT_SET(country)) AS num_countries, COUNT(*) FILTER (WHERE browser = 'Firefox') AS firefox_rows, MAX(started_at) AS ended_at, SIZE(COLLECT_SET(device)) AS num_devices FROM enriched GROUP BY 1 HAVING firefox_rows > 1 ORDER BY num_countries DESC NULLS FIRST;
